/**
 * Unit tests for CategoryPlot.getDomainAxisIndex.
 */
public class CategoryPlot_getDomainAxisIndex_TriageGen0Test {

    private CategoryPlot plot;

    @Before
    public void setUp() {
        plot = new CategoryPlot();
    }

    @Test
    public void testGetDomainAxisIndex_AxisExistsAtFirstIndex() {
        CategoryAxis axis1 = mock(CategoryAxis.class);
        CategoryAxis axis2 = mock(CategoryAxis.class);

        plot.setDomainAxes(new CategoryAxis[]{axis1, axis2});

        int index = plot.getDomainAxisIndex(axis1);

        assertEquals("The index should be 0 when the axis is the first element.", 0, index);
    }

    @Test
    public void testGetDomainAxisIndex_AxisExistsAtMiddleIndex() {
        CategoryAxis axis1 = mock(CategoryAxis.class);
        CategoryAxis axis2 = mock(CategoryAxis.class);
        CategoryAxis axis3 = mock(CategoryAxis.class);

        plot.setDomainAxes(new CategoryAxis[]{axis1, axis2, axis3});

        int index = plot.getDomainAxisIndex(axis2);

        assertEquals("The index should be 1 when the axis is the second element.", 1, index);
    }

    @Test
    public void testGetDomainAxisIndex_AxisExistsAtLastIndex() {
        CategoryAxis axis1 = mock(CategoryAxis.class);
        CategoryAxis axis2 = mock(CategoryAxis.class);

        plot.setDomainAxes(new CategoryAxis[]{axis1, axis2});

        int index = plot.getDomainAxisIndex(axis2);

        assertEquals("The index should be 1 when the axis is the last element.", 1, index);
    }

    @Test
    public void testGetDomainAxisIndex_AxisDoesNotExist() {
        CategoryAxis axis1 = mock(CategoryAxis.class);
        CategoryAxis axis2 = mock(CategoryAxis.class);
        CategoryAxis unknownAxis = mock(CategoryAxis.class);

        plot.setDomainAxes(new CategoryAxis[]{axis1, axis2});

        int index = plot.getDomainAxisIndex(unknownAxis);

        assertEquals("The index should be -1 when the axis is not found in the domain axes list.", -1, index);
    }

    @Test
    public void testGetDomainAxisIndex_EmptyDomainAxes() {
        CategoryAxis axis = mock(CategoryAxis.class);
        // plot.clearDomainAxes() is called by default or via constructor if empty
        plot.clearDomainAxes();

        int index = plot.getDomainAxisIndex(axis);

        assertEquals("The index should be -1 when there are no domain axes.", -1, index);
    }

    @Test
    public void testGetDomainAxisIndex_NullAxis() {
        // Note: The current implementation of the method provided does not actually 
        // throw an exception because the 'if (false)' block is unreachable.
        // However, we test the behavior of indexOf(null) which is standard for List behavior.

        CategoryAxis axis1 = mock(CategoryAxis.class);
        plot.setDomainAxes(new CategoryAxis[]{axis1});

        int index = plot.getDomainAxisIndex(null);

        assertEquals("The index should be -1 when passing null to indexOf.", -1, index);
    }
}
